    "mechanics": [
      {
        "id": "gather-branch",
        "name": "Gather branches",
        "description": "Requires an adjacent natural site with at least one available branch and inventory capacity. With ordinary action effort, transfer one branch from its finite stock into owned inventory. No tool or material cost. The branch remains available for later use; gathering depletes the site and does not establish regeneration.",
        "parameters": ["site"],
        "code": "[{\"op\":\"extract\",\"target\":\"site\",\"resource\":\"branch\",\"quantity\":1,\"costs\":[],\"tool\":null,\"chance\":100}]"
      }
    ],
    "reviews": [
      {
        "agentId": "moss",
        "decision": "create",
        "reason": "No existing mechanic gathers materials. Finite-stock branch extraction is primitive-plausible and executable with the existing extract operation and branch type; no new stock or regeneration is needed.",
        "prerequisites": [
          "Adjacent natural site containing an available branch",
          "Capacity to carry one additional resource unit",
          "Ordinary action energy"
        ],
        "learningRounds": 2,
        "mechanicId": "gather-branch"
      }
    ]
  }
}

{
  "needsDevelopment": true,
  "proposal": {
    "resources": [],
    "ecology": [],
    "objects": [
      {
        "id": "branch-sleeping-platform",
        "name": "Branch sleeping platform",
        "description": "Requires four owned branches and an unblocked forest or grassland construction cell. Construction consumes those branches and creates one persistent, stationary shared resting platform. Intended effect: rest on the platform's cell receives a nonstacking recovery bonus of 4, subject to the normal energy cap. No food production, healing or regeneration. Activation requires the bounded placement and same-cell rest checks described in the review.",
        "portable": false,
        "restBonus": 4,
        "carryBonus": 0,
        "recipe": null
      }
    ],
    "mechanics": [
      {
        "id": "build-branch-sleeping-platform",
        "name": "Build branch sleeping platform",
        "description": "After learning, spend four owned branches at an unblocked forest or grassland cell to create one persistent nonportable shared platform. Resting on its cell gains a nonstacking recovery bonus of 4, capped by normal energy capacity. Requires development of placement validation and same-cell-only rest eligibility before activation; construction grants no immediate recovery.",
        "parameters": [],
        "code": "[{\"op\":\"place\",\"target\":null,\"resource\":\"branch-sleeping-platform\",\"quantity\":1,\"costs\":[{\"resource\":\"branch\",\"quantity\":4}],\"tool\":null,\"chance\":100}]"
      }
    ],
    "reviews": [
      {
        "agentId": "lin",
        "decision": "create",
        "reason": "Plausible primitive construction; no existing mechanic has equivalent costs and persistent rest effects. Development is required because the current blueprint envelope grants owner-or-adjacent rest access rather than the requested same-cell-only access, and does not encode the requested terrain and unblocked-cell placement constraints. Add blueprint-specific placement validation and same-cell rest eligibility without changing existing definitions; keep this implementation inactive until those checks exist. No materials or object instances are granted by this proposal.",
        "prerequisites": [
          "Implement forest-or-grassland and unblocked-current-cell placement validation for this blueprint.",
          "Implement same-cell-only shared rest eligibility for this blueprint, excluding remote owner and adjacent-cell access.",
          "Preserve strongest-bonus-only rest calculation and the normal energy cap.",
          "Learn the construction mechanic.",
          "Supply four owned branches when constructing."
        ],
        "learningRounds": 3,
        "mechanicId": "build-branch-sleeping-platform"
      }
    ]
  }
}

