    "reviews": [
      {
        "agentId": "moss",
        "decision": "create",
        "reason": "A woody nursery is primitive-plausible and is not equivalent to gathering finite branches or cultivating food. Development is required: the existing branch type is dry wood, not a viable cutting, and the proposal envelope cannot declare a growth-only blueprint or one-unit placement. Minimum extension: define a viable woody cutting with finite, non-guaranteed natural-site availability and a collection operation; establish a nursery using one cutting plus one branch at an unoccupied forest cell. Extend the existing photosynthesis growth process to produce one collectible branch after 24 rounds, then at most one every 12 rounds, with ground-stock ceiling 2 and lifetime output 6. Record environmental growth inputs, preserve the occupied cell and lifetime budget, and allow shared pickup. No stock, object or output is created by this review; implementation must precede use.",
        "prerequisites": [
          "Implement finite viable-cutting availability and collection without refilling existing natural-site niches.",
          "Implement a forest-only woody nursery blueprint using the existing bounded growth process.",
          "For construction, own one viable cutting and one branch and occupy a forest cell without a stationary object.",
          "Harvest only actual produced ground stacks; construction provides no immediate branches."
        ],
        "learningRounds": 4,
        "mechanicId": null
      }
    ]
  }
}

{
  "needsDevelopment": true,
  "proposal": {
    "resources": [],
    "ecology": [],
    "objects": [],
    "mechanics": [],
    "reviews": [
      {
        "agentId": "moss",
        "decision": "create",
        "reason": "Reasonable primitive cultivation request, not equivalent to gathering branches or planting food. Development is required before a mechanic can be registered: the current proposal format cannot declare growth effects, placement requires at least two material units, and dry fallen branches are not viable cuttings. Implement a bounded extension for a woody nursery using one branch as nursery support plus one viable locally collected woody cutting, without creating free stock. Require an unoccupied forest cell; consume both inputs; establish for 24 rounds, then produce at most one branch every 12 rounds, with ground-stock ceiling 2 and lifetime production 6. Reuse the existing photosynthetic growth accounting and public ground pickup behavior. Preserve occupied-cell and lifetime budgets permanently; do not refill natural sites. Define a finite, capacity-bounded local cutting source before enabling collection. No nursery, material or production is created by this review.",
        "prerequisites": [
          "Development support for growth-bearing nursery blueprints and their placement validation",
          "A defined viable woody-cutting resource and finite local collection operation",
          "One owned viable woody cutting and one owned branch per nursery",
          "Current forest cell with no stationary object",
          "Persistent growth accounting with establishment 24, interval 12, ceiling 2 and lifetime 6"
        ],
        "learningRounds": 4,
        "mechanicId": null
      }
    ]
  }
}

